KG42.register("rules-d28e8f8b40c300b3932e1d85",{"id":"10-hierarchical_coordination::v141-c-R005","paper":"10-hierarchical_coordination","record":{"rule_id":"v141-c-R005","mechanism_id":"v141-a-M01","name":"Prosumer participation","process_stage":"participation","market_meaning":"Submitting an optimal bidding curve is a means of prosumer participation in the P2P market. Scope: First-stage prosumer participation through demand submission in the local P2P market. Submitting an optimal offering curve is a means of prosumer participation in the P2P market. Scope: First-stage prosumer participation through supply submission in the local P2P market. Prosumers may trade energy with each other in the P2P market. Scope: First stage of the proposed local P2P energy market. Prosumers are assumed to have grid access and may always trade with the grid at ToU selling/buying prices. Scope: Grid trading available to prosumers under the proposed model assumptions. A prosumer cannot act as both a seller and a buyer simultaneously in one time slot. Scope: Each prosumer within one time slot in the first-stage market.","independence_rationale":"Relations governed by the approved function participation.prosumer under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","bidding.supply","participation.prosumer"],"E":[{"edge_id":"v141-c-R005-E001","source":"bidding.demand","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R005-C001"],"evidence_ids":["v141-b-g01-e01","v141-b-g02-e14"]},{"edge_id":"v141-c-R005-E002","source":"bidding.supply","target":"participation.prosumer","type":"links","constraint_ids":["v141-c-R005-C002"],"evidence_ids":["v141-b-g01-e01","v141-b-g02-e14"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"Each prosumer within one time slot in the first-stage market. | First stage of the proposed local P2P energy market. | First-stage prosumer participation through demand submission in the local P2P market. | First-stage prosumer participation through supply submission in the local P2P market. | Grid trading available to prosumers under the proposed model assumptions.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e01","v141-b-g01-e03","v141-b-g01-e04","v141-b-g02-e13","v141-b-g02-e14"]},"x":[{"variable_id":"v141-c-R005-x-B-jt","symbol":"\\mathcal{B}_{jt}","meaning":"Bid vector of prosumer j at time t (source Eq. (15)): the list of bidding quantities [B_{jt1}, ..., B_{jtm}] paired with the bidding prices [\\lambda^{b}_{jt1}, ..., \\lambda^{b}_{jtm}]. It is the object whose submission to the local market operator constitutes first-stage prosumer participation through demand submission (constraint C001, edge E001). No formal expression is asserted for C001 itself, which the source states only procedurally.","kind":"operational","domain":"ordered pair of an m-block list of non-negative bidding quantities and the corresponding list of bidding prices, declared for each prosumer j and time slot t","unit":null,"indices":["j","t","m"],"evidence_ids":["v141-b-g01-e14","v141-b-g02-e12","v141-b-g01-en3"]},{"variable_id":"v141-c-R005-x-O-jt","symbol":"\\mathcal{O}_{jt}","meaning":"Offer vector of prosumer j at time t (source Eq. (14)): the list of offering quantities [O_{jt1}, ..., O_{jtm}] paired with the offering prices [\\lambda^{o}_{jt1}, ..., \\lambda^{o}_{jtm}]. It is the object whose submission to the local market operator constitutes first-stage prosumer participation through supply submission (constraint C002, edge E002). No formal expression is asserted for C002 itself, which the source states only procedurally.","kind":"operational","domain":"ordered pair of an m-block list of non-negative offering quantities and the corresponding list of offering prices, declared for each prosumer j and time slot t","unit":null,"indices":["j","t","m"],"evidence_ids":["v141-b-g01-e14","v141-b-g02-e12","v141-b-g01-en3"]},{"variable_id":"v141-c-R005-x-P-minus-jtomega","symbol":"P^{-}_{jt\\omega}","meaning":"Total energy purchased by prosumer j at time slot t and scenario \\omega; per Eq. (4) it equals the local (LEM) purchased quantity P^{lm,-}_{jt\\omega} plus the energy purchased from the grid P^{g,-}_{jt\\omega}. In the buy-or-sell exclusivity condition (Eq. (6)) it is bounded above by L_{jt\\omega} v_{jt\\omega}, so it can be positive only when v_{jt\\omega} = 1.","kind":"operational","domain":"P^{-}_{jt\\omega} >= 0 (Eq. (6) left inequality); upper bound L_{jt\\omega} v_{jt\\omega} with binary v_{jt\\omega}","unit":"kWh","indices":["j","t","\\omega"],"evidence_ids":["v141-b-g02-e06","v141-b-g01-e09","v141-b-g01-e08","v141-b-g01-en3"]},{"variable_id":"v141-c-R005-x-P-plus-jtomega","symbol":"P^{+}_{jt\\omega}","meaning":"Total energy sold by prosumer j at time slot t and scenario \\omega; per Eq. (5) it equals the local (LEM) sold quantity P^{lm,+}_{jt\\omega} plus the energy sold to the grid P^{g,+}_{jt\\omega}. In the buy-or-sell exclusivity condition (Eq. (7)) it is bounded above by P_{jt\\omega} (1 - v_{jt\\omega}), so it can be positive only when v_{jt\\omega} = 0.","kind":"operational","domain":"P^{+}_{jt\\omega} >= 0 (Eq. (7) left inequality); upper bound P_{jt\\omega} (1 - v_{jt\\omega}) with binary v_{jt\\omega}","unit":"kWh","indices":["j","t","\\omega"],"evidence_ids":["v141-b-g02-e06","v141-b-g01-e09","v141-b-g01-e08","v141-b-g01-en3"]},{"variable_id":"v141-c-R005-x-v-jtomega","symbol":"v_{jt\\omega}","meaning":"Binary variable expressing the buying/selling status in the LEM of prosumer j at time slot t and scenario \\omega (source nomenclature). v_{jt\\omega} = 1 selects the buying side and v_{jt\\omega} = 0 the selling side in Eqs. (6)-(7); this binary is the mathematical form of the C005 exclusivity statement that a prosumer cannot be both a seller and a buyer in one time slot.","kind":"operational","domain":"{0, 1}","unit":null,"indices":["j","t","\\omega"],"evidence_ids":["v141-b-g01-en3","v141-b-g02-e06","v141-b-g01-e09"]}],"theta":[{"parameter_id":"v141-c-R005-th-L-jtomega","symbol":"L_{jt\\omega}","meaning":"Energy consumption of prosumer j at time slot t and scenario \\omega, listed by the source under 'Parameters in the first stage'. Within this rule it is the exogenous prosumer-level input that bounds the purchased quantity in the exclusivity condition (Eq. (6): 0 \u003c= P^{-}_{jt\\omega} \u003c= L_{jt\\omega} v_{jt\\omega}). No numeric value is given for this rule's scope.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["j","t","\\omega"],"evidence_ids":["v141-b-g01-en3","v141-b-g02-e06"]},{"parameter_id":"v141-c-R005-th-P-jtomega","symbol":"P_{jt\\omega}","meaning":"Energy generation of prosumer j at time slot t and scenario \\omega, listed by the source under 'Parameters in the first stage'. Within this rule it is the exogenous prosumer-level input that bounds the sold quantity in the exclusivity condition (Eq. (7): 0 \u003c= P^{+}_{jt\\omega} \u003c= P_{jt\\omega} (1 - v_{jt\\omega})). No numeric value is given for this rule's scope.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":"kWh","indices":["j","t","\\omega"],"evidence_ids":["v141-b-g01-en3","v141-b-g02-e06"]}],"phi":[{"constraint_id":"v141-c-R005-C001","kind":"procedural","role":"core","statement":"Submitting an optimal bidding curve is a means of prosumer participation in the P2P market. Scope: First-stage prosumer participation through demand submission in the local P2P market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e01","v141-b-g02-e14"]},{"constraint_id":"v141-c-R005-C002","kind":"procedural","role":"core","statement":"Submitting an optimal offering curve is a means of prosumer participation in the P2P market. Scope: First-stage prosumer participation through supply submission in the local P2P market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e01","v141-b-g02-e14"]},{"constraint_id":"v141-c-R005-C003","kind":"procedural","role":"core","statement":"Prosumers may trade energy with each other in the P2P market. Scope: First stage of the proposed local P2P energy market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e03"]},{"constraint_id":"v141-c-R005-C004","kind":"procedural","role":"core","statement":"Prosumers are assumed to have grid access and may always trade with the grid at ToU selling/buying prices. Scope: Grid trading available to prosumers under the proposed model assumptions.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.prosumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-e04"]},{"constraint_id":"v141-c-R005-C005","kind":"mathematical","role":"core","statement":"A prosumer cannot act as both a seller and a buyer simultaneously in one time slot. Scope: Each prosumer within one time slot in the first-stage market.","expression":"0 \\leq P^{-}_{jt\\omega} \\leq L_{jt\\omega} v_{jt\\omega}, \\quad 0 \\leq P^{+}_{jt\\omega} \\leq P_{jt\\omega} (1 - v_{jt\\omega}), \\quad v_{jt\\omega} \\in \\{0,1\\}, \\quad \\forall j, \\forall t, \\forall \\omega","formalization_origin":"source","template_id":null,"members":["participation.prosumer"],"variable_refs":["v141-c-R005-x-P-minus-jtomega","v141-c-R005-x-P-plus-jtomega","v141-c-R005-x-v-jtomega"],"parameter_refs":["v141-c-R005-th-L-jtomega","v141-c-R005-th-P-jtomega"],"evidence_ids":["v141-b-g02-e13","v141-b-g02-e06","v141-b-g01-e09","v141-b-g01-en3"]}],"pi":[{"evidence_id":"v141-b-g01-e01","location":{"location_id":"src-87ebdce2a6-p01-c2r2__v141-a-M01-participation","page":1,"printed_page":null,"section":"Abstract","anchor_text":"a Razzaghi b, Hannu Laaksonen c, T), 76131 Karlsruhe, Germany n VIC 3800, Australia l role in curren","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"restatement"},"source_text":"In this paper, we propose a hierarchical approach for local energy and flexibility trading among prosumers in distribution networks, in which prosumers are able to trade energy via P2P manner and transact flexibility in the local energy market to maintain distribution network constraints. The proposed method enables prosumers to manage their resources and participate in a P2P market by submitting their optimal bidding and offering curves. A local market operator runs the P2P market for energy trading among prosumers, and cooperates with the distribution system operator to dispatch the flexibility provided by prosumers."},{"evidence_id":"v141-b-g01-e03","location":{"location_id":"src-87ebdce2a6-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":"3","section":"2. Proposed local energy market model","anchor_text":"flexibility is defined as an electricity commodity which is provided by ty flexible power system pla","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"restatement"},"source_text":"According to our proposed LEM structure, in the first stage, prosumers are able to trade with each other in a P2P energy market, where the LMO is in charge of coordinating P2P tradings among them. In the second stage, the LMO in cooperation with the DSO dispatches the flexibility provided by prosumers considering distribution network constraints."},{"evidence_id":"v141-b-g01-e04","location":{"location_id":"src-87ebdce2a6-p03-c2r4__v141-a-M01-participation","page":3,"printed_page":"3","section":"2. Proposed local energy market model","anchor_text":"flexibility is defined as an electricity commodity which is provided by ty flexible power system pla","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"condition"},"source_text":"In our proposed model, we assume that: Prosumers have access to grid and can always trade with the grid at time of use (ToU) selling/buying prices, Prosumers have their own autonomous energy management systems that act on behalf of them in the local market and generate bids and offers, Prosumers and the LMO can communicate with each other through a communication platform."},{"evidence_id":"v141-b-g02-e13","location":{"location_id":"src-87ebdce2a6-p05-c1r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"2.1.1. Bidding strategy for prosumers","anchor_text":"P2 where both 𝜔and 𝜔′ represent scenarios (offering/bidding blocks). In bi other words, Eqs. (12) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"Moreover, it is noted that each prosumer cannot act as a seller and a buyer in one time slot simultaneously."},{"evidence_id":"v141-b-g02-e14","location":{"location_id":"src-87ebdce2a6-p05-c1r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"2.1.1. Bidding strategy for prosumers","anchor_text":"P2 where both 𝜔and 𝜔′ represent scenarios (offering/bidding blocks). In bi other words, Eqs. (12) an","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Thus, the decision making problem of prosumer j in the bottom layer of the distribution network is given as: min OF^{p}_{j}  s.t. : (4)-(13)  In this way, prosumer j is able to make optimal decisions based on bidding strategy independently, and submits its offers or bids in each time slot."},{"evidence_id":"v141-b-g01-e08","location":{"location_id":"src-87ebdce2a6-p04-c2r2__v141-a-M01-bidding","page":4,"printed_page":"4","section":"2.1.1. Bidding strategy for prosumers","anchor_text":"work for energy and flexibility trading in the LEM. LEM which are obtained based on prediction by pr","equation_id":"(4),(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"P^{-}_{jt\\omega} = P^{lm,-}_{jt\\omega} + P^{g,-}_{jt\\omega}, \\forall j, \\forall t, \\forall \\omega \\qquad (4)\nP^{+}_{jt\\omega} = P^{lm,+}_{jt\\omega} + P^{g,+}_{jt\\omega}, \\forall j, \\forall t, \\forall \\omega \\qquad (5)"},{"evidence_id":"v141-b-g01-e09","location":{"location_id":"src-87ebdce2a6-p04-c2r3__v141-a-M01-bidding","page":4,"printed_page":"4","section":"2.1.1. Bidding strategy for prosumers","anchor_text":"energy exchanged with the grid as seen in Eqs. (4) and (5): 𝑃−𝑗𝑡𝜔= 𝑃𝑙𝑚,−𝑗𝑡𝜔 + 𝑃𝑔,−𝑗𝑡𝜔, ∀𝑗, ∀𝑡, ∀𝜔 (4","equation_id":"(6),(7),(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"0 \\leq P^{-}_{jt\\omega} \\leq L_{jt\\omega} v_{jt\\omega}, \\forall j, \\forall t, \\forall \\omega \\qquad (6)\n0 \\leq P^{+}_{jt\\omega} \\leq P_{jt\\omega}(1 - v_{jt\\omega}), \\forall j, \\forall t, \\forall \\omega \\qquad (7)\nP_{jt\\omega} + P^{-}_{jt\\omega} = L_{jt\\omega} - Lf_{jt\\omega} + P^{+}_{jt\\omega}, \\forall j, \\forall t, \\forall \\omega \\qquad (8)"},{"evidence_id":"v141-b-g01-e14","location":{"location_id":"src-87ebdce2a6-p05-c1r2__v141-a-M01-bidding","page":5,"printed_page":"5","section":"2.1.1. Bidding strategy for prosumers","anchor_text":"P2 where both 𝜔and 𝜔′ represent scenarios (offering/bidding blocks). In bi other words, Eqs. (12) an","equation_id":"(14),(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"O_{jt} = \\{[O_{jt1}, \\ldots, O_{jtm}], [\\lambda^{o}_{jt1}, \\ldots, \\lambda^{o}_{jtm}]\\}, \\forall j, \\forall t \\qquad (14)\nB_{jt} = \\{[B_{jt1}, \\ldots, B_{jtm}], [\\lambda^{b}_{jt1}, \\ldots, \\lambda^{b}_{jtm}]\\}, \\forall j, \\forall t \\qquad (15)\nMoreover, it is noted that each prosumer cannot act as a seller and a buyer in one time slot simultaneously."},{"evidence_id":"v141-b-g01-en3","location":{"location_id":"src-87ebdce2a6-p02-c1r3__v141-a-M01-bidding","page":2,"printed_page":"2","section":"Nomenclature","anchor_text":"𝑡 g g 𝜆−𝑡 ToU buying price from the grid at time slot 𝑡 𝐿𝑗 Maximum energy consumption for pro- sumer","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Parameters in the first stage: \\beta_{jt} Portion of interruptible loads for prosumer j at time slot t which is between 0 and 1; \\lambda^{lm}_{jt\\omega} Predicted energy trading price in the LEM for prosumer j at time slot t and scenario \\omega; \\lambda^{+}_{t} ToU selling price to the grid at time slot t; \\lambda^{-}_{t} ToU buying price from the grid at time slot t; \\bar{L}_{j} Maximum energy consumption for prosumer j; \\bar{P}_{j} Maximum energy generation (PV capacity) for prosumer j; \\rho_{\\omega} Probability of scenario \\omega; L_{jt\\omega} Energy consumption for prosumer j at time slot t and scenario \\omega; P_{jt\\omega} Energy generation for prosumer j at time slot t and scenario \\omega. Variables in the first stage: \\lambda^{p2p}_{jit} The price of P2P energy trading between prosumers j and i at time slot t; \\lambda^{b}_{jtm} Bidding price of prosumer j in block m and time t; \\lambda^{o}_{jtm} Offering price of prosumer j in block m and time t; O_{jt} Offer vector for prosumer j at time t; B_{jt} Bid vector for prosumer j at time t; B_{jtm} Bidding quantity of prosumer j in block m and time t; O_{jtm} Offering quantity of prosumer j in block m and time t; EC^{p}_{j} Expected cost for prosumer j; EP^{p}_{j} Expected profit for prosumer j; Lf,i_{jt\\omega} The amount of interruptible load for prosumer j at time t and scenario \\omega; Lf,s_{jt\\omega} The amount of shiftable load for prosumer j at time t and scenario \\omega; OF^{p}_{j} Objective function for prosumer j; P^{p2p,+,bl}_{jitm} The quantity of offering for P2P trading among prosumers j and i at time slot t and block m; P^{p2p,+}_{jit} Energy that prosumer j sells to prosumer i at time slot t; P^{p2p,-,bl}_{jitm} The quantity of bidding for P2P trading among prosumers j and i at time slot t and block m; P^{p2p,-}_{jit} Energy that prosumer j buys from prosumer i at time slot t; P^{+}_{jt\\omega} Total energy sold of prosumer j at time slot t and scenario \\omega; P^{-}_{jt\\omega} Total energy purchased of prosumer j at time slot t and scenario \\omega; P^{g,+}_{jt\\omega} Energy sold to the grid at ToU price by prosumer j at time slot t and scenario \\omega; P^{g,-}_{jt\\omega} Energy purchased from the grid at ToU price to prosumer j at time slot t and scenario \\omega; P^{lm,+}_{jt\\omega} Energy quantities of offering for prosumer j at time slot t and scenario \\omega; P^{lm,-}_{jt\\omega} Energy quantities of bidding for prosumer j at time slot t and scenario \\omega; u_{jit} A binary variable representing P2P trading status between prosumers j and i at time slot t; v_{jt\\omega} A binary variable for expressing status of buying/selling in the LEM of prosumer j at time slot t and scenario \\omega."},{"evidence_id":"v141-b-g02-e06","location":{"location_id":"src-87ebdce2a6-p04-c2r3__v141-a-M01-bidding","page":4,"printed_page":null,"section":"2.1.1. Bidding strategy for prosumers","anchor_text":"energy exchanged with the grid as seen in Eqs. (4) and (5): 𝑃−𝑗𝑡𝜔= 𝑃𝑙𝑚,−𝑗𝑡𝜔 + 𝑃𝑔,−𝑗𝑡𝜔, ∀𝑗, ∀𝑡, ∀𝜔 (4","equation_id":"(6)-(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"condition"},"source_text":"Moreover, each prosumer is able to participate only as a seller or a buyer of energy at time slot t and scenario \\omega as represented in (6) and (7): 0 \\leq P^{-}_{jt\\omega} \\leq L_{jt\\omega} v_{jt\\omega}, \\forall j, \\forall t, \\forall \\omega   (6)   0 \\leq P^{+}_{jt\\omega} \\leq P_{jt\\omega} (1 - v_{jt\\omega}), \\forall j, \\forall t, \\forall \\omega   (7) where L_{jt\\omega} and P_{jt\\omega} represent energy consumption and generation of prosumer j at time t and scenario \\omega, and v_{jt\\omega} is a binary variable for expressing status of buying/selling in the LEM."},{"evidence_id":"v141-b-g02-e12","location":{"location_id":"src-87ebdce2a6-p05-c1r2__v141-a-M01-bidding","page":5,"printed_page":null,"section":"2.1.1. Bidding strategy for prosumers","anchor_text":"P2 where both 𝜔and 𝜔′ represent scenarios (offering/bidding blocks). In bi other words, Eqs. (12) an","equation_id":"(14)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Thus, optimal offering and bidding blocks are ordered according to Eqs. (12) and (13) as seen in Eqs. (14) and (15): \\mathcal{O}_{jt} = \\{[O_{jt1}, ..., O_{jtm}], [\\lambda^{o}_{jt1}, ..., \\lambda^{o}_{jtm}]\\}, \\forall j, \\forall t   (14)   \\mathcal{B}_{jt} = \\{[B_{jt1}, ..., B_{jtm}], [\\lambda^{b}_{jt1}, ..., \\lambda^{b}_{jtm}]\\}, \\forall j, \\forall t   (15) where \\mathcal{O}_{jt} and \\mathcal{B}_{jt} represent offer and bid vectors for prosumers j at time t. Besides, O_{jtm} and \\lambda^{o}_{jtm} state offering quantity and price of prosumer j in block m and time t, and B_{jtm} and \\lambda^{b}_{jtm} express bidding quantity and price of prosumer j in block m and time t."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-participation","v141-a-M04-coordination","v141-a-M04-participation"],"extras":{"decision_anchor":"participation.prosumer","graph_fact_supports":[[{"evidence_id":"v141-b-g01-e01","quote":"The proposed method enables prosumers to manage their resources and participate in a P2P market by submitting their optimal bidding and offering curves."},{"evidence_id":"v141-b-g02-e14","quote":"In this way, prosumer j is able to make optimal decisions based on bidding strategy independently, and submits its offers or bids in each time slot."}],[{"evidence_id":"v141-b-g01-e01","quote":"The proposed method enables prosumers to manage their resources and participate in a P2P market by submitting their optimal bidding and offering curves."},{"evidence_id":"v141-b-g02-e14","quote":"In this way, prosumer j is able to make optimal decisions based on bidding strategy independently, and submits its offers or bids in each time slot."}],[{"evidence_id":"v141-b-g01-e03","quote":"in the first stage, prosumers are able to trade with each other in a P2P energy market"}],[{"evidence_id":"v141-b-g01-e04","quote":"Prosumers have access to grid and can always trade with the grid at time of use (ToU) selling/buying prices"}],[{"evidence_id":"v141-b-g02-e13","quote":"Moreover, it is noted that each prosumer cannot act as a seller and a buyer in one time slot simultaneously."}]],"C2_formalization":{"graph_sha256":"43590b2f44a3209017eeba422957af7f8bbb6d65181c1d78f24288070f6522ef","applicability":"formalized","reason":"v141-c-R005 is the first-stage prosumer-participation rule of mechanism v141-a-M01, with frozen V = {bidding.demand, bidding.supply, participation.prosumer} and the two 'links' edges E001/E002. Four of its five constraints are source-stated procedural/admission statements that contain no source equation: C001 and C002 state that submitting an optimal bidding (resp. offering) curve is a means of prosumer participation (the two existing links edges), C003 states that prosumers may trade energy with each other in the first stage, and C004 is a modelling assumption of grid access at ToU selling/buying prices (the ToU price symbols and the DSO are outside this rule's frozen V and are therefore not introduced). These four remain expression=null / formalization_origin=not_formalized with their C.1 statements, roles, members and original evidence preserved. C005 is the one constraint of this rule for which the source supplies explicit mathematics: the source states the verbal exclusivity ('each prosumer cannot act as a seller and a buyer in one time slot simultaneously', evidence v141-b-g02-e13) and represents it by Eqs. (6)-(7) with the binary buy/sell status variable v_{jt\\omega} ('each prosumer is able to participate only as a seller or a buyer of energy at time slot t and scenario \\omega as represented in (6) and (7)'). Its expression is a faithful transcription of Eqs. (6)-(7) plus the binary domain stated in the nomenclature (formalization_origin=source), using only symbols defined by the same mechanism: v_{jt\\omega}, P^{-}_{jt\\omega}, P^{+}_{jt\\omega} (variables) and L_{jt\\omega}, P_{jt\\omega} (listed by the source under 'Parameters in the first stage'). The bid/offer vectors B_{jt} and O_{jt} are declared as x because they are the submission objects explicitly named by C001/C002 and because the rule's own edges E001/E002 exist precisely for their submission. Two points are reported rather than resolved: (i) the source describes v_{jt\\omega} as the LEM buying/selling status yet applies the bounds of Eqs. (6)-(7) to total purchased/sold energy P^{\\pm}_{jt\\omega}, which Eq. (4)-(5) split into a local (P^{lm,\\pm}) and a grid (P^{g,\\pm}) component; (ii) the frozen graph has function-level nodes only (no variable-level nodes), so the x objects are bound to the existing function nodes and to the existing edges without creating any new edge. All B evidence used here is UNREVIEWED candidate support under source_review_policy.mode = unreviewed_candidates_by_user; no source audit, independent review or scientific acceptance is claimed.","bindings":[{"object_id":"v141-c-R005-x-B-jt","node_ids":["bidding.demand"],"edge_ids":["v141-c-R005-E001"],"rationale":"The bid vector B_{jt} is the demand-submission object of prosumer j; the frozen edge E001 (bidding.demand -> participation.prosumer, constraint C001) is the relation in which that object is submitted as a means of participation. Node/edge identities are used as given; no new relation is created and no formal expression is asserted for C001."},{"object_id":"v141-c-R005-x-O-jt","node_ids":["bidding.supply"],"edge_ids":["v141-c-R005-E002"],"rationale":"The offer vector O_{jt} is the supply-submission object of prosumer j; the frozen edge E002 (bidding.supply -> participation.prosumer, constraint C002) is the relation in which that object is submitted as a means of participation. Node/edge identities are used as given; no formal expression is asserted for C002."},{"object_id":"v141-c-R005-x-P-minus-jtomega","node_ids":["bidding.demand","participation.prosumer"],"edge_ids":["v141-c-R005-E001"],"rationale":"P^{-}_{jt\\omega} is the total purchased energy of prosumer j, whose local component is the demand-side bid quantity, so it is attached to the bidding.demand node and, as the quantity whose status is restricted by the prosumer's buy/sell participation role, to participation.prosumer through the existing link E001. The local/grid split is registered by evidence v141-b-g01-e08 (Eqs. (4)-(5)); this rule's graph contains no variable-level node."},{"object_id":"v141-c-R005-x-P-plus-jtomega","node_ids":["bidding.supply","participation.prosumer"],"edge_ids":["v141-c-R005-E002"],"rationale":"P^{+}_{jt\\omega} is the total sold energy of prosumer j, whose local component is the supply-side offering quantity, so it is attached to the bidding.supply node and, as the quantity whose status is restricted by the prosumer's buy/sell participation role, to participation.prosumer through the existing link E002. The local/grid split is registered by evidence v141-b-g01-e08 (Eqs. (4)-(5))."},{"object_id":"v141-c-R005-x-v-jtomega","node_ids":["participation.prosumer"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002"],"rationale":"v_{jt\\omega} is the binary buy/sell status attribute attached to the prosumer participation node; in the source it selects which side of the prosumer's participation can carry positive quantity, i.e. which of the two existing participation links (E001 demand side / E002 supply side) may be active in a time slot and scenario. No edge is added or modified."},{"object_id":"v141-c-R005-th-L-jtomega","node_ids":["participation.prosumer"],"edge_ids":[],"rationale":"L_{jt\\omega} is the prosumer j's exogenous energy consumption listed among the source's first-stage parameters; inside this rule it enters only as the upper-bound input of the buy/sell exclusivity condition on the participation node, so it is bound to participation.prosumer without a relation edge."},{"object_id":"v141-c-R005-th-P-jtomega","node_ids":["participation.prosumer"],"edge_ids":[],"rationale":"P_{jt\\omega} is the prosumer j's exogenous energy generation listed among the source's first-stage parameters; inside this rule it enters only as the upper-bound input of the buy/sell exclusivity condition on the participation node, so it is bound to participation.prosumer without a relation edge."},{"object_id":"v141-c-R005-C005","node_ids":["participation.prosumer","bidding.demand","bidding.supply"],"edge_ids":["v141-c-R005-E001","v141-c-R005-E002"],"rationale":"The exclusivity constraint is stated at the prosumer participation node and forbids simultaneous positive purchased (P^{-}) and sold (P^{+}) quantities, i.e. simultaneous activation of the two participation relations of this frozen graph: E001 (demand-submission link) and E002 (supply-submission link). Both edges are referenced because the constraint is about their joint activation; no edge between bidding.demand and bidding.supply exists in this rule and none is introduced."}],"revision_requests":[]}},"quarantined_references":[]}});
